function generateWebDynaPathToken(params) {
  if (!params || !params.seed) {
    throw new Error('seed (string from /dynaPath.do) is required');
  }
  const seed = params.seed;
  const targetUrl = params.url || '/classes/com.korail.mobile.seatMovie.ScheduleView';
  let prefix = params.prefix;
  if (!prefix) {
    if (targetUrl.includes('ScheduleView') || targetUrl.includes('schedule')) {
      prefix = 'web_s';
    } else if (targetUrl.includes('TicketReservation') || targetUrl.includes('reserve')) {
      prefix = 'web_r';
    } else {
      prefix = 'dynaPath';
    }
  }

  const method = (params.method || 'POST').toUpperCase();
  const body = params.body || null;

  const window = {
    addEventListener: () => {},
    removeEventListener: () => {},
    atob: (value) => {
      if (typeof globalThis.atob === 'function') return globalThis.atob(value);
      return Buffer.from(value, 'base64').toString('binary');
    },
    btoa: (value) => {
      if (typeof globalThis.btoa === 'function') return globalThis.btoa(value);
      return Buffer.from(value, 'binary').toString('base64');
    },
    TextEncoder: typeof TextEncoder !== 'undefined' ? TextEncoder : undefined,
    TextDecoder: typeof TextDecoder !== 'undefined' ? TextDecoder : undefined,
    Navigator: NavigatorClass,
    Document: DocumentClass,
    Window: WindowClass,
    Screen: ScreenClass,
    WebGLRenderingContext: WebGLRenderingContextClass,
    localStorage: createStorage(),
    sessionStorage: createStorage(),
    requestAnimationFrame: () => {},
    cancelAnimationFrame: () => {},
    performance: {
      now: () => Date.now(),
      getEntriesByType: () => [{ type: 'navigate', startTime: 0, responseStart: 100, responseEnd: 150 }]
    },
    document: {
      addEventListener: () => {},
      removeEventListener: () => {},
      getElementsByTagName: () => [],
      getElementsByClassName: () => [],
      getElementById: () => null,
      querySelector: () => null,
      querySelectorAll: () => [],
      createElement: (tag) => {
        if (tag === 'canvas') {
          return {
            getContext: () => ({
              getExtension: () => null,
              getParameter: () => 'WebGL 1.0',
              createBuffer: () => ({}),
              bindBuffer: () => {},
              bufferData: () => {},
              createProgram: () => ({}),
              linkProgram: () => {},
              getProgramParameter: () => true
            }),
            width: 300,
            height: 150
          };
        }
        if (tag === 'a') {
          const anchor = {
            protocol: 'https:',
            host: 'www.korail.com',
            pathname: '/',
            search: '',
            _href: ''
          };
          Object.defineProperty(anchor, 'href', {
            get() { return this._href; },
            set(value) {
              this._href = value;
              try {
                const parsed = new URL(value, 'https://www.korail.com');
                this.protocol = parsed.protocol;
                this.host = parsed.host;
                this.pathname = parsed.pathname;
                this.search = parsed.search;
              } catch (_) {
                this.pathname = value;
              }
            }
          });
          return anchor;
        }
        if (tag === 'iframe') {
          return {
            style: {},
            setAttribute: () => {},
            contentWindow: { eval: eval, Function: Function }
          };
        }
        return {
          style: {},
          setAttribute: () => {},
          appendChild: () => {},
          removeChild: () => {},
          addEventListener: () => {},
          getElementsByTagName: () => []
        };
      },
      documentElement: { clientWidth: 412, clientHeight: 915, appendChild: () => {}, removeChild: () => {} },
      body: { clientWidth: 412, clientHeight: 915, appendChild: () => {}, removeChild: () => {} },
      head: { appendChild: () => {} },
      cookie: '',
      referrer: 'https://www.korail.com/ticket/login',
      title: '코레일'
    },
    location: {
      href: 'https://www.korail.com/ticket/login',
      protocol: 'https:',
      host: 'www.korail.com',
      origin: 'https://www.korail.com',
      pathname: '/ticket/login'
    },
    navigator: new NavigatorClass(),
    screen: new ScreenClass(),
    innerWidth: 412,
    innerHeight: 915,
    outerWidth: 412,
    outerHeight: 915,
    devicePixelRatio: 2.625,
    setTimeout: () => {},
    setInterval: () => {},
    clearTimeout: () => {},
    clearInterval: () => {},
    console: { log: () => {}, error: () => {} },
    Date: Date,
    Math: Math,
    Buffer: typeof Buffer !== 'undefined' ? Buffer : undefined
  };

  Object.assign(window.navigator, {
    userAgent: 'Mozilla/5.0 (Linux; Android 10; K) AppleWebKit/537.36 (KHTML, like Gecko) SamsungBrowser/30.0 Chrome/143.0.0.0 Mobile Safari/537.36',
    hardwareConcurrency: 8,
    platform: 'Linux armv8l',
    language: 'ko-KR',
    languages: ['ko-KR', 'ko', 'en-US', 'en'],
    maxTouchPoints: 5,
    vendor: 'Google Inc.'
  });
  Object.assign(window.screen, {
    width: 412,
    height: 915,
    availWidth: 412,
    availHeight: 915,
    colorDepth: 24,
    pixelDepth: 24
  });
  window.window = window;
  window.self = window;
  window.document.defaultView = window;

  const codeToRun = '(function(g4yc) { ' + RAW_BUNDLE_CODE + ' })(' + JSON.stringify(seed) + ');';
  if (vm) {
    vm.runInContext(codeToRun, vm.createContext(window));
  } else {
    const runDirect = new Function(
      'window',
      'code',
      'with (window) { return eval(code); }'
    );
    runDirect(window, codeToRun);
  }

  if (typeof window.__dynapathRouter !== 'function') {
    throw new Error('compiled bundle did not export a router function');
  }
  const routeResult = window.__dynapathRouter(targetUrl, method, null, body, { p: prefix });
  const routeParts = window.__dynapathRouteParts;
  const sessionHash = window.__dynapathSessionHash;
  if (!Array.isArray(routeParts) || routeParts.length < 3 || !sessionHash) {
    throw new Error('compiled bundle did not export route state');
  }

  const tokenParam = "hc_";
  const tokenPrefix = "hc_=";
  const routeUrl = String(routeResult["tr"] || '');
  const bodyValue = String(routeResult["ne7"] || '');
  const queryValue = (url, name) => {
    const queryIndex = url.indexOf('?');
    if (queryIndex < 0) return '';
    const pairs = url.slice(queryIndex + 1).split('&');
    for (const pair of pairs) {
      const separator = pair.indexOf('=');
      const key = separator < 0 ? pair : pair.slice(0, separator);
      if (key === name) return separator < 0 ? '' : pair.slice(separator + 1);
    }
    return '';
  };
  let tokenValue = '';
  if (bodyValue.startsWith(tokenPrefix)) {
    tokenValue = bodyValue.slice(tokenPrefix.length).split('&', 1)[0];
  }
  if (!tokenValue) {
    tokenValue = queryValue(routeUrl, tokenParam);
  }
  if (!tokenValue) {
    throw new Error('compiled router returned no token value');
  }

  const requestHash = routeParts[1] || '';
  const path = '/' + prefix + '/' + sessionHash + '/' + requestHash;
  const fullUrl = queryValue(routeUrl, tokenParam)
    ? routeUrl
    : routeUrl + (routeUrl.includes('?') ? '&' : '?') + tokenParam + '=' + tokenValue;

  return {
    prefix: prefix,
    sessionHash: sessionHash,
    requestHash: requestHash,
    tokenVal: tokenValue,
    z9Token: tokenValue,
    atkToken: tokenValue,
    wycToken: tokenValue,
    tjToken: tokenValue,
    dxToken: tokenValue,
    tokenParam: "hc_",
    path: path,
    fullUrl: fullUrl,
    timeKey: '',
    kV: '',
    config: {}
  };
}

function detectBundleFromScript(scriptText) {
  if (!vm) {
    return null;
  }
  let targetBundleUrl = null;
  const mockWindow = {
    XMLHttpRequest: function() {
      return {
        open: function(_method, url) { targetBundleUrl = url; },
        send: function() {}
      };
    },
    document: {
      createElement: () => ({ setAttribute: () => {}, appendChild: () => {} }),
      head: { appendChild: () => {} }
    },
    location: { href: 'https://www.korail.com/ticket/login' }
  };
  mockWindow.window = mockWindow;
  mockWindow.self = mockWindow;
  try {
    vm.runInContext(scriptText, vm.createContext(mockWindow));
  } catch (_) {}
  return targetBundleUrl;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { generateWebDynaPathToken, detectBundleFromScript };
}
if (typeof globalThis !== 'undefined') {
  globalThis.generateWebDynaPathToken = generateWebDynaPathToken;
  globalThis.detectBundleFromScript = detectBundleFromScript;
}

if (typeof process !== 'undefined' && process.argv && require.main === module) {
  const args = process.argv.slice(2);
  let seed = '';
  let url = '/classes/com.korail.mobile.certification.TicketReservation';
  let prefix = null;
  let body = '';
  let profile = {};
  let detectScript = null;

  for (let index = 0; index < args.length; index += 1) {
    if (args[index] === '--seed' && args[index + 1]) {
      seed = args[++index];
    } else if (args[index] === '--url' && args[index + 1]) {
      url = args[++index];
    } else if (args[index] === '--prefix' && args[index + 1]) {
      prefix = args[++index];
    } else if (args[index] === '--body' && args[index + 1]) {
      body = args[++index];
    } else if (args[index] === '--profile' && args[index + 1]) {
      profile = JSON.parse(args[++index]);
    } else if (args[index] === '--detect-bundle' && args[index + 1]) {
      detectScript = args[++index];
    }
  }

  if (detectScript !== null) {
    process.stdout.write(JSON.stringify({ bundleUrl: detectBundleFromScript(detectScript) }));
    process.exit(0);
  }
  if (!seed) {
    console.error('Error: --seed argument is required');
    process.exit(1);
  }

  try {
    const result = generateWebDynaPathToken({ seed, url, prefix, body, profile });
    process.stdout.write(JSON.stringify(result));
  } catch (error) {
    console.error('Error generating token:', error && error.message ? error.message : error);
    process.exit(1);
  }
}
